static bool touch_rect(float x,float y,const Placement& p,float l,float t,float r,float b){
 return p.w>0&&p.h>0&&x>=p.x+p.w*l&&x<p.x+p.w*r&&y>=p.y+p.h*t&&y<p.y+p.h*b;
}
static bool touch_inverse_fit(float& x,float& y,float sw,float sh,float dw,float dh){const float scale=std::min(dw/sw,dh/sh);x=(x-(dw-sw*scale)/2)/scale;y=(y-(dh-sh*scale)/2)/scale;return x>=0&&x<sw&&y>=0&&y<sh;}
